def solve(g,fill=2):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bgv,_=cnt.most_common(1)[0]
    order=[v for v,_ in cnt.most_common()]
    sc=order[-1]
    S={(r,c) for r in range(H) for c in range(W) if g[r][c]==sc}
    rs_={r for r,c in S}; cc_={c for r,c in S}
    min_r=min(rs_); max_r=max(rs_); min_c=min(cc_); max_c=max(cc_)
    out=[row[:] for row in g]
    # border cells of bbox that are bg get filled
    for r in range(min_r,max_r+1):
        for c in range(min_c,max_c+1):
            if (r,c) in ((min_r,c),(max_r,c),(r,min_c),(r,max_c)):
                if g[r][c]==bgv: out[r][c]=fill
    return out
