def enclosed(inp):
    H,W=len(inp),len(inp[0])
    cnt=Counter(x for row in inp for x in row); bg=max(cnt,key=lambda c:cnt[c])
    seen=[[False]*W for _ in range(H)]; out=set()
    q=deque()
    for r in range(H):
        for c in range(W):
            if inp[r][c]==bg and ((r in(0,H-1)) or (c in(0,W-1))) and not seen[r][c]:
                seen[r][c]=True; out.add((r,c)); q.append((r,c))
    while q:
        y,x=q.popleft()
        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
            n=(y+dy,x+dx)
            if 0<=n[0]<H and 0<=n[1]<W and inp[n[0]][n[1]]==bg and n not in out and not seen[n[0]][n[1]]:
                seen[n[0]][n[1]]=True; out.add(n); q.append(n)
    return out,bg
