        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def cross(g):
    H,W=len(g),len(g[0])
    cnt=collections.Counter(x for row in g for x in row)
    bg=max(cnt,key=lambda k:cnt[k])
    S={(r,c) for r in range(H) for c in range(W) if g[r][c]!=bg}
    Rset={r for r,c in S}; Cset={c for r,c in S}
    out=[list(row) for row in g]
    for r in range(H):
        for c in range(W):
            if (r,c) not in S and r in Rset and c in Cset: out[r][c]=2
    return out
